function documentDigits(value){return String(value==null?'':value).replace(/\D/g,'')}
function formatDocument(value){
 var d=documentDigits(value);
 // Never pad an identifier or discard excess digits: an overlong value must fail validation.
 if(d.length>14)return d;
 if(d.length<=11)return d.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3}\.\d{3})(\d)/,'$1.$2').replace(/(\.\d{3})(\d{1,2})$/,'$1-$2');
 return d.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2}\.\d{3})(\d)/,'$1.$2').replace(/(\.\d{3})(\d)/,'$1/$2').replace(/(\/\d{4})(\d{1,2})$/,'$1-$2');
}
function validDocument(value){
 var d=documentDigits(value),sum=0,i,check;
 if(!/^\d+$/.test(d)||/^(\d)\1+$/.test(d))return false;
 if(d.length===11){
  for(i=0;i<9;i++)sum+=Number(d.charAt(i))*(10-i);
  check=(sum*10)%11;if(check===10)check=0;if(check!==Number(d.charAt(9)))return false;
  sum=0;for(i=0;i<10;i++)sum+=Number(d.charAt(i))*(11-i);
  check=(sum*10)%11;if(check===10)check=0;return check===Number(d.charAt(10));
 }
 if(d.length!==14)return false;
 var weights=[5,4,3,2,9,8,7,6,5,4,3,2];
 for(i=0;i<12;i++)sum+=Number(d.charAt(i))*weights[i];
 check=sum%11;check=check<2?0:11-check;if(check!==Number(d.charAt(12)))return false;
 sum=0;weights=[6,5,4,3,2,9,8,7,6,5,4,3,2];
 for(i=0;i<13;i++)sum+=Number(d.charAt(i))*weights[i];
 check=sum%11;return (check<2?0:11-check)===Number(d.charAt(13));
}
function maskDocumentInput(){
 var input=document.getElementById('cpfCnpj'),old=input.value,start=input.selectionStart,end=input.selectionEnd;
 var beforeStart=documentDigits(old.slice(0,start==null?old.length:start)).length,beforeEnd=documentDigits(old.slice(0,end==null?old.length:end)).length;
 input.value=formatDocument(old);input.setCustomValidity('');
 function caret(count){if(!count)return 0;var seen=0;for(var i=0;i<input.value.length;i++){if(/\d/.test(input.value.charAt(i)))seen++;if(seen===count)return i+1}return input.value.length}
 if(start!=null&&end!=null)input.setSelectionRange(caret(beforeStart),caret(beforeEnd));
}
